# -*- coding: utf-8 -*-
# --- Automatic dependency setup (no CMD needed) ---
import importlib.util, subprocess, sys, tkinter as _tk, re, json
from tkinter import messagebox as _mb
def _ensure_package(package, import_name=None, optional=False):
    name = import_name or package
    if importlib.util.find_spec(name) is not None:
        return True
    root = _tk.Tk(); root.withdraw()
    ok = _mb.askyesno("רכיב חסר", f"הרכיב {package} אינו מותקן.\n\nהתוכנה יכולה להתקין אותו אוטומטית עכשיו, בלי CMD.\n\nלהתקין?")
    if not ok:
        root.destroy()
        return False
    try:
        subprocess.check_call([sys.executable, "-m", "pip", "install", package])
        root.destroy()
        return importlib.util.find_spec(name) is not None
    except Exception as e:
        _mb.showerror("התקנה נכשלה", f"לא הצלחתי להתקין את {package}.\n\n{e}\n\nבדוק שיש חיבור לאינטרנט ונסה שוב.")
        root.destroy()
        return False

if not _ensure_package("Pillow", "PIL"):
    raise SystemExit

