try:
    from PIL import BmpImagePlugin, GifImagePlugin, JpegImagePlugin, PngImagePlugin, TiffImagePlugin, WebPImagePlugin, PpmImagePlugin, IcoImagePlugin, TgaImagePlugin, PcxImagePlugin, IptcImagePlugin
    for _plugin in (BmpImagePlugin, JpegImagePlugin, PngImagePlugin, GifImagePlugin, TiffImagePlugin, WebPImagePlugin):
        try: Image.register_open(_plugin.format, _plugin, _plugin._accept)
        except Exception: pass
except Exception:
    pass
