def _decode_mmi_template(s):
    return zlib.decompress(base64.b64decode(''.join(s.split())))


@dataclass
class Res:
    idx:int; kind:str; off:int; size:int; w:int=0; h:int=0
    changed:bool=False; data:bytes=None; name:str=''; parent:str=''; is_file:bool=False
    @property
    def end(self): return self.off+self.size
    @property
    def label(self): return self.name or self.kind



class NativeImgCodec:
    """Bridge to the ImgOptm.dll C++ image codec shipped with ResOver.
    The DLL is 32-bit and its methods are __thiscall, so ctypes needs a tiny
    x86 thunk. If the native codec cannot be loaded, proprietary resources are
    deliberately kept read-only rather than writing invalid PNG/BMP bytes into
    a compressed MMI resource.
    """
    def __init__(self):
        self.ok=False; self.reason=''
        self.dll=None; self.obj=None; self.thunks=[]
        if os.name!='nt' or struct.calcsize('P')!=4:
            self.reason='ImgOptm.dll is 32-bit; install/run 32-bit Python on Windows.'; return
        try:
            base=Path(__file__).resolve().parent
            for d in (base, base/'native', base/'resover_native'):
                if d.exists() and hasattr(os,'add_dll_directory'):
                    try:self._dll_dir=os.add_dll_directory(str(d))
                    except Exception:pass
            self.dll=ctypes.WinDLL(str(base/'ImgOptm.dll'))
            self._make = getattr(self.dll,'??0CImagOptImp@@QAE@XZ')
            self._extract = getattr(self.dll,'?X_IMG_ExtractBmp@CImagOptImp@@UAE_NPBEPAPAEPAKK@Z')
            self._compress = getattr(self.dll,'?X_IMG_CompressBmp@CImagOptImp@@UAE_NPBEPAPAEPAKK@Z')
            self._free = getattr(self.dll,'?X_IMG_xFreeMem@CImagOptImp@@UAEXPAX@Z')
            self.obj=ctypes.create_string_buffer(8)
            self._call(self._make, 0, (ctypes.c_void_p,), self.obj)
            self.ok=True
        except Exception as e:self.reason=str(e)
    def _call(self,fn,restype,args,*vals):
        addr=ctypes.cast(fn,ctypes.c_void_p).value
        # pop return; pop this; push return; jmp target
        code=bytearray(b'\x58\x59\x50\xE9\x00\x00\x00\x00')
        ctypes.memmove(0, b'', 0) if False else None
        va=ctypes.windll.kernel32.VirtualAlloc(None,len(code),0x3000,0x40)
        if not va: raise OSError('VirtualAlloc failed')
        rel=addr-(va+8)
        code[4:8]=struct.pack('<i',rel)
        ctypes.memmove(va,bytes(code),len(code)); self.thunks.append(va)
        F=ctypes.CFUNCTYPE(restype,*args)
        return F(va)(*vals)
    def _extract_bytes(self,data):
        if not self.ok:return None
        inp=ctypes.create_string_buffer(data)
        out=ctypes.c_void_p(); sz=ctypes.c_uint32(); w=ctypes.c_uint32(); h=ctypes.c_uint32()
        good=self._call(self._extract,ctypes.c_bool,(ctypes.c_void_p,ctypes.c_void_p,ctypes.POINTER(ctypes.c_void_p),ctypes.POINTER(ctypes.c_uint32),ctypes.POINTER(ctypes.c_uint32),ctypes.POINTER(ctypes.c_uint32)),self.obj,inp,ctypes.byref(out),ctypes.byref(sz),ctypes.byref(w),ctypes.byref(h))
        if not good or not out.value or not sz.value:return None
        raw=ctypes.string_at(out.value,sz.value)
        try:self._call(self._free,None,(ctypes.c_void_p,ctypes.c_void_p),self.obj,out)
        except Exception:pass
        return raw
    def _compress_bytes(self,bmp):
        if not self.ok:return None
        inp=ctypes.create_string_buffer(bmp)
        out=ctypes.c_void_p(); sz=ctypes.c_uint32(); w=ctypes.c_uint32(); h=ctypes.c_uint32()
        good=self._call(self._compress,ctypes.c_bool,(ctypes.c_void_p,ctypes.c_void_p,ctypes.POINTER(ctypes.c_void_p),ctypes.POINTER(ctypes.c_uint32),ctypes.POINTER(ctypes.c_uint32),ctypes.POINTER(ctypes.c_uint32)),self.obj,inp,ctypes.byref(out),ctypes.byref(sz),ctypes.byref(w),ctypes.byref(h))
        if not good or not out.value or not sz.value:return None
        raw=ctypes.string_at(out.value,sz.value)
        try:self._call(self._free,None,(ctypes.c_void_p,ctypes.c_void_p),self.obj,out)
        except Exception:pass
        return raw
    def decode(self,data): return self._extract_bytes(data)
    def encode(self,bmp): return self._compress_bytes(bmp)

class Scanner:
    """PAC-aware scanner. First reads the real Unisoc PAC file table, then
    scans each real payload for standard image/audio containers. This avoids
    losing most files by searching only for image signatures in the whole PAC.
    """
    RECORD_FALLBACK=2580
    def __init__(self,b): self.b=b; self.n=len(b)
    def positions(self,s,limit=None):
        p=0; c=0
        while True:
            p=self.b.find(s,p)
            if p<0:return
            yield p; p+=1; c+=1
            if limit and c>=limit:return
    def txt(self,b):
        try:return b.decode('utf-16le','ignore').split('\x00')[0].strip()
        except:return ''
    def img_end(self,p,kind,limit=None):
        try:
            bio=io.BytesIO(self.b[p:] if limit is None else self.b[p:p+limit])
            im=Image.open(bio); im.load(); end=bio.tell()
            if kind=='GIF':
                q=self.b.find(b'\x3b',p+10,p+(limit or self.n-p))
                if q>=0:end=max(end,q+1-p)
            return end,im.size
        except Exception:return None,(0,0)
    def jpeg_end(self,p,limit=None):
        # PAC payloads can contain trailing padding or a JPEG stream with unusual
        # marker layout. Try EOI candidates and accept only one Pillow can decode.
        stop=min(self.n,p+(limit or self.n-p)); q=p+2
        while q+1<stop:
            eoi=self.b.find(b'\xff\xd9',q,stop)
            if eoi<0: return None
            end=eoi+2
            try:
                with Image.open(io.BytesIO(self.b[p:end])) as im:
                    im.load()
                    if im.format=='JPEG' and im.width>0 and im.height>0:return end-p
            except Exception:
                pass
            q=eoi+2
        return None
    def bmp(self,p,limit=None):
        stop=min(self.n,p+(limit or self.n-p))
        if p+54>stop:return None,(0,0)
        sz=int.from_bytes(self.b[p+2:p+6],'little')
        pixel=int.from_bytes(self.b[p+10:p+14],'little')
        dib=int.from_bytes(self.b[p+14:p+18],'little')
        w=int.from_bytes(self.b[p+18:p+22],'little',signed=True)
        h=int.from_bytes(self.b[p+22:p+26],'little',signed=True)
        planes=int.from_bytes(self.b[p+26:p+28],'little')
        bpp=int.from_bytes(self.b[p+28:p+30],'little')
        comp=int.from_bytes(self.b[p+30:p+34],'little')
        if dib not in (12,40,52,56,108,124) or planes!=1 or not w or not h:return None,(0,0)
        if bpp not in (1,2,4,8,16,24,32) or comp not in (0,1,2,3,6,0x1003):return None,(0,0)
        if pixel<14+dib or pixel>=stop-p:return None,(0,0)
        # If the BMP file-size field is absent/wrong (common in packed resources),
        # derive the standard uncompressed raster size from dimensions/bit depth.
        aw,ah=abs(w),abs(h)
        if aw>8192 or ah>8192:return None,(aw,ah)
        row=((aw*bpp+31)//32)*4
        expected=pixel+row*ah
        if 0<sz<=stop-p and sz>=pixel and sz<=expected+4096:
            return min(sz,stop-p),(aw,ah)
        if comp==0 and expected<=stop-p and expected>pixel:
            return expected,(aw,ah)
        return None,(aw,ah)
    def _riff_end(self,p,end):
        if p+12>end or self.b[p:p+4]!=b'RIFF': return None,None
        total=8+int.from_bytes(self.b[p+4:p+8],'little')
        if total<12 or p+total>end: return None,None
        typ=self.b[p+8:p+12]
        return total, ('WAV' if typ==b'WAVE' else 'WEBP' if typ==b'WEBP' else None)

    def _mp3_end(self,p,end):
        q=p
        if self.b[q:q+3]==b'ID3' and q+10<=end:
            flags=self.b[q+5]; n=0
            for x in self.b[q+6:q+10]: n=(n<<7)|(x&0x7f)
            q=min(end,q+10+n+(10 if flags&0x10 else 0))
        start=q; frames=0; last=q
        while q+4<=end:
            h=int.from_bytes(self.b[q:q+4],'big')
            if (h & 0xFFE00000)!=0xFFE00000: break
            ver=(h>>19)&3; layer=(h>>17)&3; br=(h>>12)&15; sr=(h>>10)&3; pad=(h>>9)&1
            if layer!=1 or ver==1 or br in (0,15) or sr==3: break
            rates={0:[22050,24000,16000],2:[22050,24000,16000],3:[44100,48000,32000]}
            srate=rates[ver][sr]
            brtab=([0,32,40,48,56,64,80,96,112,128,160,192,224,256,320,0] if ver==3 else [0,8,16,24,32,40,48,56,64,80,96,112,128,144,160,0])
            bitrate=brtab[br]*1000
            flen=(144*bitrate//srate)+pad if ver==3 else (72*bitrate//srate)+pad
            if flen<24 or q+flen>end: break
            frames+=1; q+=flen; last=q
        return last-p if frames>=2 else None

    def _adts_end(self,p,end):
        q=p; frames=0
        while q+7<=end and self.b[q]==0xff and (self.b[q+1]&0xf6)==0xf0:
            h=self.b[q:q+7]; ln=((h[3]&3)<<11)|(h[4]<<3)|(h[5]>>5)
            if ln<7 or q+ln>end: break
            q+=ln; frames+=1
        return q-p if frames>=2 else None

    def _midi_end(self,p,end):
        if p+14>end or self.b[p:p+4]!=b'MThd': return None
        hlen=int.from_bytes(self.b[p+4:p+8],'big'); tracks=int.from_bytes(self.b[p+10:p+12],'big'); q=p+8+hlen
        if not (1<=tracks<=64): return None
        for _ in range(tracks):
            if q+8>end or self.b[q:q+4]!=b'MTrk': return None
            ln=int.from_bytes(self.b[q+4:q+8],'big'); q+=8+ln
            if q>end: return None
        return q-p

    def _amr_end(self,p,end):
        if self.b[p:p+9]==b'#!AMR-WB\n': hdr=b'#!AMR-WB\n'; sizes=[18,24,33,37,41,47,51,59,61,6,0,0,0,0,0,0]
        elif self.b[p:p+6]==b'#!AMR\n': hdr=b'#!AMR\n'; sizes=[13,14,16,18,20,21,27,32,6,0,0,0,0,0,0,0]
        else: return None
        q=p+len(hdr); frames=0
        while q<end:
            ft=(self.b[q]>>3)&15; ln=sizes[ft] if ft<len(sizes) else 0
            if not ln: break
            q+=ln; frames+=1
        return q-p if frames>=2 else None

    def _trim_zero_end(self,p,end):
        q=end
        # Resource containers commonly pad audio slots with zero bytes.
        while q>p and self.b[q-1] in (0,0xff): q-=1
        return max(p,q)

    def _ogg_end(self,p,end):
        q=p; pages=0; last=p
        while q+27<=end and self.b[q:q+4]==b'OggS':
            segs=self.b[q+26]
            if q+27+segs>end: break
            body=sum(self.b[q+27:q+27+segs])
            page=27+segs+body
            if page<27 or q+page>end: break
            q+=page; last=q; pages+=1
        if pages>=1:
            return self._trim_zero_end(p,last)-p
        return None

    def _flac_end(self,p,end):
        if p+4>end or self.b[p:p+4]!=b'fLaC': return None
        q=p+4
        # Parse metadata blocks. The last metadata block is followed by frames.
        last_meta=False
        while q+4<=end and not last_meta:
            h=self.b[q]
            last_meta=bool(h & 0x80)
            ln=int.from_bytes(self.b[q+1:q+4],'big')
            q += 4+ln
            if q>end: return None
        # FLAC frames have no simple global footer; trim padding from the slot.
        return self._trim_zero_end(p,end)-p if q<=end else None

    def _asf_end(self,p,end):
        # ASF starts with GUID + 64-bit object size.
        if p+30>end or self.b[p:p+4]!=b'\x30\x26\xb2\x75': return None
        try:
            sz=int.from_bytes(self.b[p+16:p+24],'little')
        except Exception:
            return None
        if 30<=sz<=end-p:
            return sz
        return self._trim_zero_end(p,end)-p

    def _box_end(self,p,end):
        if p+8>end:return None
        size=int.from_bytes(self.b[p:p+4],'big')
        if size==1 and p+16<=end:size=int.from_bytes(self.b[p+8:p+16],'big')
        if size==0:return end-p
        return size if 8<=size<=end-p else None

    def scan_range(self,start,size,parent=''):
        out=[]; end=min(self.n,start+size); local=self.b[start:end]
        def add(kind,p,e,w=0,h=0):
            if e and e>p+16 and p>=start and p<end:
                out.append(Res(0,kind,p,e-p,w,h,parent=parent))
        for kind,sig in [('PNG',b'\x89PNG\r\n\x1a\n'),('GIF',b'GIF87a'),('GIF',b'GIF89a'),('BMP',b'BM'),('TIFF',b'II*\x00'),('TIFF',b'MM\x00*')]:
            q=0
            while True:
                q=local.find(sig,q)
                if q<0:break
                p=start+q; lim=end-p
                e,(w,h)=self.img_end(p,kind,lim)
                if kind=='BMP':e,(w,h)=self.bmp(p,lim)
                if e:add(kind,p,p+e,w,h)
                q+=1
        q=0
        while True:
            q=local.find(b'\xff\xd8\xff',q)
            if q<0:break
            p=start+q; e=self.jpeg_end(p,end-p)
            if e:
                try: wh=Image.open(io.BytesIO(self.b[p:p+e])).size
                except: wh=(0,0)
                add('JPEG',p,p+e,*wh)
            q+=1
        for q in self._positions_local(local,b'RIFF'):
            p=start+q; e,kind=self._riff_end(p,end)
            if e and kind=='WAV': add('WAV',p,p+e)
        for sig in (b'ID3',b'\xff\xfb',b'\xff\xf3',b'\xff\xf2'):
            for q in self._positions_local(local,sig):
                p=start+q; e=self._mp3_end(p,end)
                if e:add('MP3',p,p+e)
        for q in self._positions_local(local,b'OggS'):
            p=start+q
            e=self._ogg_end(p,end)
            if e:add('OGG',p,p+e)
        for q in self._positions_local(local,b'fLaC'):
            p=start+q
            e=self._flac_end(p,end)
            if e:add('FLAC',p,p+e)
        for q in self._positions_local(local,b'#!AMR'):
            p=start+q; e=self._amr_end(p,end)
            if e:add('AMR',p,p+e)
        for sig in (b'\xff\xf1',b'\xff\xf9'):
            for q in self._positions_local(local,sig):
                p=start+q; e=self._adts_end(p,end)
                if e:add('AAC',p,p+e)
        for q in self._positions_local(local,b'MThd'):
            p=start+q; e=self._midi_end(p,end)
            if e:add('MIDI',p,p+e)
        for q in self._positions_local(local,b'ftyp'):
            p=max(start,start+q-4); e=self._box_end(p,end)
            if e:add('M4A',p,p+e)
        for q in self._positions_local(local,b'FORM'):
            p=start+q; e=self._box_end(p,end)
            if e and p+12<=end and self.b[p+8:p+12] in (b'AIFF',b'AIFC'):add('AIFF',p,p+e)
        for q in self._positions_local(local,b'\x30\x26\xb2\x75'):
            p=start+q
            e=self._asf_end(p,end)
            if e:add('WMA',p,p+e)
        # remove duplicate/contained signatures
        out.sort(key=lambda r:(r.off,-r.size)); clean=[]
        for r in out:
            if any(q.off<=r.off and q.end>=r.end and q.kind==r.kind and q.size>r.size for q in clean):continue
            if any(q.kind==r.kind and q.off==r.off for q in clean):continue
            clean.append(r)
        return clean
    def _positions_local(self,b,s):
        p=0
        while True:
            p=b.find(s,p)
            if p<0:return
            yield p; p+=1
    def pac_files(self):
        # Real Unisoc PAC header: count at 1076, table start at 1080.
        if self.n<1120:return []
        count=struct.unpack_from('<I',self.b,1076)[0]
        start=struct.unpack_from('<I',self.b,1080)[0]
        if not (1<=count<=512) or start<2000 or start>=self.n:return []
        out=[]; p=start
        for i in range(count):
            if p+8>self.n:break
            rec_len=struct.unpack_from('<I',self.b,p)[0]
            if rec_len<1568 or rec_len>16384 or p+rec_len>self.n: rec_len=self.RECORD_FALLBACK
            rec=self.b[p:p+rec_len]
            name=self.txt(rec[4:516]); fn=self.txt(rec[516:1028])
            # This Nokia/UMS9117 PAC stores the effective 32-bit size/offset
            # in the fields at 1540 and 1552 (despite legacy names hi*).
            size=struct.unpack_from('<I',rec,1540)[0]
            off=struct.unpack_from('<I',rec,1552)[0]
            if name or fn:
                if size>0 and off+size<=self.n:
                    out.append(Res(0,'FILE',off,size,name=(name + '  —  ' + fn) if name and fn else (name or fn),parent='',is_file=True))
                else:
                    out.append(Res(0,'ENTRY',0,0,name=(name + '  —  ' + fn) if name and fn else (name or fn),parent='',is_file=True))
            p+=rec_len
        return out
    def scan(self, deep=True):
        files=self.pac_files()
        if not files:
            return self.scan_range(0,self.n)
        out=[]
        for f in files:
            out.append(f)
            if not deep or not f.size:
                continue
            fn=(f.name+' '+f.label).lower()
            base=(f.name.split('—',1)[0].strip().lower() if f.name else '')
            should_deep=(base in ('mmires','userimg') or any(x in fn for x in ('.png','.jpg','.jpeg','.gif','.bmp','.tif','.tiff','.webp','.wav','.mp3','.ogg','.flac','.mid','.midi','.amr','.aac','.m4a','.aiff','.wma')))
            if not should_deep: continue
            sub=self.scan_range(f.off,f.size,f.name or f.label)
            for r in sub:
                r.name=f'{r.kind} @ 0x{r.off:08X}'
                out.append(r)
        for i,r in enumerate(out,1):r.idx=i
        return out


class Editor(tk.Toplevel):
    def __init__(self,master,res,img,apply):
        super().__init__(master);self.res=res;self.base=img.convert('RGBA');self.img=self.base.copy();self.apply_cb=apply
        self.title('עורך תמונה');self.geometry('920x650');self.configure(bg='#0b1220')
        top=tk.Frame(self,bg='#111827');top.pack(fill='x',padx=12,pady=12)
        tk.Label(top,text='עורך תמונה',fg='white',bg='#111827',font=('Segoe UI',18,'bold')).pack(side='left')
        self.inf=tk.Label(top,fg='#94a3b8',bg='#111827');self.inf.pack(side='right')
        self.cv=tk.Canvas(self,bg='#050a12',highlightthickness=0);self.cv.pack(fill='both',expand=True,padx=12,pady=(0,8))
        bar=tk.Frame(self,bg='#111827');bar.pack(fill='x',padx=12,pady=8)
        def B(t,c):
            return RoundedButton(bar,t,c,'#1f2937',width=max(82,min(150,len(t)*7+26)))
        for t,c in [('↶ שמאלה',lambda:self.set(self.img.rotate(90,expand=True))),('↷ ימינה',lambda:self.set(self.img.rotate(-90,expand=True))),('↔ היפוך',lambda:self.set(ImageOps.mirror(self.img))),('↕ אנכי',lambda:self.set(ImageOps.flip(self.img))),('◐ אפור',lambda:self.set(ImageOps.grayscale(self.img).convert('RGBA'))),('📐 גודל',self.resize),('✂ חיתוך',self.crop),('↺ איפוס',lambda:self.set(self.base.copy()))]:B(t,c).pack(side='left',padx=2)
        bot=tk.Frame(self,bg='#111827');bot.pack(fill='x',padx=12,pady=(0,12))
        RoundedButton(bot,'ביטול',self.destroy,'#374151',width=92).pack(side='right',padx=4)
        RoundedButton(bot,'✓ החל',self.commit,'#2563eb',width=92).pack(side='right',padx=4)
        self.bind('<Configure>',lambda e:self.refresh());self.refresh()
    def set(self,x):self.img=x.convert('RGBA');self.refresh()
    def refresh(self):
        if not self.winfo_exists():return
        self.cv.delete('all');im=self.img.copy();im.thumbnail((self.cv.winfo_width()-30,self.cv.winfo_height()-30),Image.Resampling.LANCZOS)
        self.tk=ImageTk.PhotoImage(im);self.cv.create_image(self.cv.winfo_width()//2,self.cv.winfo_height()//2,image=self.tk)
        self.inf.config(text=f'{self.img.width} × {self.img.height} px')
    def resize(self):
        w,h=self.img.size
        d=simpledialog.askstring('גודל',f'הזן רוחב,גובה (נוכחי {w},{h}):',parent=self)
        if not d:return
        try:nw,nh=map(int,re.split(r'[, xX]+',d.strip()));self.set(self.img.resize((nw,nh),Image.Resampling.LANCZOS))
        except Exception:messagebox.showerror('שגיאה','לדוגמה: 240,320',parent=self)
    def crop(self):
        w,h=self.img.size;d=simpledialog.askstring('חיתוך',f'X,Y,W,H (נוכחי {w},{h}):',parent=self)
        if not d:return
        try:x,y,cw,ch=map(int,re.split(r'[, xX]+',d.strip()));self.set(self.img.crop((x,y,x+cw,y+ch)))
        except Exception:messagebox.showerror('שגיאה','לדוגמה: 0,0,120,160',parent=self)
    def commit(self):self.apply_cb(self.img,self.res);self.destroy()

class RoundedButton(tk.Canvas):
    """Small modern rounded button drawn on Canvas; retains normal pack/grid behavior."""
    def __init__(self, master, text, command, color='#2563eb', **kwargs):
        self.label_text=text; self.command=command; self.color=color
        self.hover_color=self._mix(color, '#ffffff', 0.13)
        self.pressed=False
        # Compact width is based on the label, so header actions no longer consume the whole row.
        requested_width = kwargs.pop('width', max(78, min(154, len(text) * 7 + 24)))
        super().__init__(master, width=requested_width, height=34, bg=master.cget('bg'), highlightthickness=0, bd=0,
                         cursor='hand2', **kwargs)
        self.configure(width=requested_width, height=34)
        self.bind('<Configure>', lambda _e: self._draw())
        self.bind('<Enter>', self._enter); self.bind('<Leave>', self._leave)
        self.bind('<ButtonPress-1>', self._press); self.bind('<ButtonRelease-1>', self._release)
        self._draw()
    @staticmethod
    def _mix(a,b,amount):
        try:
            aa=tuple(int(a[i:i+2],16) for i in (1,3,5)); bb=tuple(int(b[i:i+2],16) for i in (1,3,5))
            return '#'+''.join(f'{round(aa[i]*(1-amount)+bb[i]*amount):02x}' for i in range(3))
        except Exception: return a
    def _draw(self):
        self.delete('all')
        w=max(12,self.winfo_width()); h=max(12,self.winfo_height())
        fill=getattr(self,'_fill',self.color)
        # Draw a true pill with rounded end caps; inset avoids clipped edge pixels.
        r=max(1,(h-4)//2)
        y0=2; y1=h-2
        self.create_rectangle(r+1,y0,w-r-1,y1,fill=fill,outline=fill)
        self.create_oval(1,y0,2*r+1,y1,fill=fill,outline=fill)
        self.create_oval(w-2*r-1,y0,w-1,y1,fill=fill,outline=fill)
        self.create_text(w//2,h//2,text=self.label_text,fill='white',font=('Segoe UI',9,'bold'))
    def _enter(self,_e=None): self._fill=self.hover_color; self._draw()
    def _leave(self,_e=None): self.pressed=False; self._fill=self.color; self._draw()
    def _press(self,_e=None): self.pressed=True; self._fill=self._mix(self.color,'#000000',.13); self._draw()
    def _release(self,e=None):
        inside=e is None or (0<=e.x<=self.winfo_width() and 0<=e.y<=self.winfo_height())
        self.pressed=False; self._fill=self.hover_color if inside else self.color; self._draw()
        if inside and callable(self.command): self.command()

