        for c,t,w in zip(cols,heads,[75,250,120,110,110,80]):self.tree.heading(c,text=t);self.tree.column(c,width=w,anchor='center')
        self.tree.pack(side='left',fill='both',expand=True);sc=ttk.Scrollbar(tf,orient='vertical',command=self.tree.yview);sc.pack(side='right',fill='y');self.tree.configure(yscrollcommand=sc.set);self.tree.bind('<<TreeviewSelect>>',self.select)
