        for t,c,col in [('📤 ייצא',self.export,'#374151'),('🔄 החלף',self.replace,'#2563eb'),('🖌 ערוך תמונה',self.edit,'#7c3aed'),('🧩 RGB565',self.decode565_dialog,'#8b5cf6'),('▶ נגן',self.play,'#059669'),('⏹ עצור',self.stop,'#b91c1c')]:self.button(a,t,c,col).pack(side='left',fill='x',expand=True,padx=2)
