    def device_settings(self):
        """Inspect the settings labels and category icon resources extracted from the opened PAC."""
        if not self.data or not self.rs:
            messagebox.showwarning('הגדרות מהקושחה', 'פתח קובץ PAC ובצע סריקה לפני פתיחת דפדפן ההגדרות.', parent=self)
            return
        mmi_res = None
        mmi_entry = None
        for res in self.rs:
            if not getattr(res, 'is_file', False) or not getattr(res, 'size', 0):
                continue
            base_name = (getattr(res, 'name', '') or '').split('—', 1)[0].strip().lower()
            if base_name == 'mmires':
                try:
                    mmi_res = self.bytes(res)
                    mmi_entry = res
                    break
                except Exception:
                    pass
        if not mmi_res:
            messagebox.showwarning('הגדרות מהקושחה', 'לא נמצאה מחיצת MMIRes ב-PAC הפתוח. יש לפתוח את קובץ הקושחה של Nokia 225, לא תמונה או קובץ בודד.', parent=self)
            return
        mmi_res = bytes(mmi_res)

        # User-defined names are stored alongside the tool, while the actual
        # string edits (when safe in-place) are stored in the MMIRes PAC resource.
        rename_db_path = Path(__file__).with_name('Nokia225_PAC_Studio_setting_names_v31.json')
        try:
            _rename_doc = json.loads(rename_db_path.read_text(encoding='utf-8')) if rename_db_path.exists() else {}
            setting_name_overrides = _rename_doc.get('entries', {}) if isinstance(_rename_doc, dict) else {}
            if not isinstance(setting_name_overrides, dict): setting_name_overrides = {}
        except Exception:
            setting_name_overrides = {}
        _mmi_size_key = str(len(mmi_res))

        def read_label_at(offset, kind):
            try:
                offset = int(offset)
                if offset < 0 or offset >= len(mmi_res): return None
                if kind == 'UTF-16LE resource string':
                    if offset + 4 > len(mmi_res) or mmi_res[offset:offset+2] != b'\x80\x00': return None
                    ln = int.from_bytes(mmi_res[offset+2:offset+4], 'little')
                    if ln < 2 or ln % 2 or offset + 4 + ln > len(mmi_res): return None
                    return mmi_res[offset+4:offset+4+ln].decode('utf-16le').rstrip('\x00')
                end = mmi_res.find(b'\x00', offset, min(len(mmi_res), offset+161))
                if end < 0: return None
                return mmi_res[offset:end].decode('ascii')
            except Exception:
                return None

        def saved_override(setting_id):
            if not setting_id: return None
            record = setting_name_overrides.get(f'{_mmi_size_key}:{setting_id}')
            if not isinstance(record, dict):
                # MMIRes grows when a longer label is safely relocated, so the size
                # part of the sidecar key may be from the pre-edit firmware. Only
                # accept a fallback record after verifying the actual bytes at its
                # stored offset; stale display-only aliases are never used.
                candidates = [v for k, v in setting_name_overrides.items()
                              if k.endswith(':' + setting_id) and isinstance(v, dict)]
                for candidate in reversed(candidates):
                    actual_candidate = read_label_at(candidate.get('offset', -1), candidate.get('kind', ''))
                    if candidate.get('editor_schema') == 31 and candidate.get('verified_firmware_ref') and candidate.get('firmware_applied', True) and actual_candidate == candidate.get('title'):
                        record = candidate
                        break
                if not isinstance(record, dict): return None
            actual = read_label_at(record.get('offset', -1), record.get('kind', ''))
            if record.get('editor_schema') != 31 or not record.get('verified_firmware_ref') or not record.get('firmware_applied', True) or actual != record.get('title'):
                return None
            return {'title': record.get('title', actual), 'offset': int(record['offset']), 'kind': record['kind'], 'source_alias': 'שם מותאם אישית', 'setting_id': setting_id, 'verified_source': True, 'source_pool_rank': 0, 'source_ref_count': 2}

        # Collect actual strings in MMIRes. Both resource strings (0x80 + UTF-16LE
        # byte length) and ordinary NUL-terminated ASCII strings are supported.
        # Offsets always refer to the extracted MMIRes payload, not to guessed IDs.
        string_occurrences = {}
        def clean_label(value):
            value = ''.join(ch for ch in value if ch not in '\u200e\u200f\u202a\u202b\u202c\u202d\u202e\u2066\u2067\u2068\u2069\ufeff')
            return value.strip().strip('\x00').strip()
        def label_key(value):
            value = clean_label(value).casefold()
            return re.sub(r'[\s:：]+$', '', value)
        def add_string(offset, value, source_kind):
            value = clean_label(value)
            if len(value) < 2 or len(value) > 160:
                return
            if not any(ch.isalpha() for ch in value):
                return
            if any(ord(ch) < 32 for ch in value):
                return
            key = label_key(value)
            if not key:
                return
            entry = (int(offset), value, source_kind)
            bucket = string_occurrences.setdefault(key, [])
            if entry not in bucket:
                bucket.append(entry)

        for match in re.finditer(b'\x80\x00', mmi_res):
            pos = match.start()
            if pos + 4 > len(mmi_res):
                continue
            byte_len = int.from_bytes(mmi_res[pos + 2:pos + 4], 'little')
            if byte_len < 2 or byte_len > 512 or (byte_len & 1) or pos + 4 + byte_len > len(mmi_res):
                continue
            try:
                text_value = mmi_res[pos + 4:pos + 4 + byte_len].decode('utf-16le').rstrip('\x00')
            except Exception:
                continue
            add_string(pos, text_value, 'UTF-16LE resource string')

        for match in re.finditer(rb'[\x20-\x7e]{2,100}\x00{1,4}', mmi_res):
            try:
                text_value = match.group().rstrip(b'\x00').decode('ascii')
            except Exception:
                continue
            add_string(match.start(), text_value, 'ASCII resource string')

        def occurrences_for(alias):
            return string_occurrences.get(label_key(alias), [])
        def reference_score(entry):
            pos, value, source_kind = entry
            base = (pos // 0x10000) * 0x10000
            # Check record-start and UTF-16 payload-start offsets. Only aligned
            # DWORD matches count; arbitrary values inside string bytes do not.
            vals = {pos - base}
            if source_kind == 'UTF-16LE resource string':
                vals.add(pos + 4 - base)
            score = 0
            for v in vals:
                if v < 0 or v > 0xFFFFFFFF:
                    continue
                needle = struct.pack('<I', v)
                at = 0
                while True:
                    at = mmi_res.find(needle, at)
                    if at < 0:
                        break
                    if at % 4 == 0 and not (at < pos + 4 and at + 4 > pos):
                        score += 1
                    at += 1
            return score

        _ref_score_cache = {}
        def score_occurrence(entry):
            key = (entry[0], entry[2])
            if key not in _ref_score_cache:
                _ref_score_cache[key] = reference_score(entry)
            return _ref_score_cache[key]

        def pick_occurrence(alias, prefer_main_pool=True):
            found = occurrences_for(alias)
            if not found:
                return None
            larger_hebrew = len(mmi_res) >= 5_500_000
            def rank(entry):
                pos, value, source_kind = entry
                if larger_hebrew:
                    if 0x445000 <= pos < 0x447500: pool_rank = 0
                    elif label_key(alias) in ('stk', 'אחסון') and 0x260000 <= pos < 0x280000: pool_rank = 0
                    elif 0x440000 <= pos < 0x480000: pool_rank = 1
                    elif 0x260000 <= pos < 0x280000: pool_rank = 2
                    elif 0x400000 <= pos < 0x420000: pool_rank = 3
                    else: pool_rank = 5
                else:
                    if 0x409000 <= pos < 0x40C000: pool_rank = 0
                    elif 0x413000 <= pos < 0x416000: pool_rank = 1
                    elif label_key(alias) in ('stk', 'אחסון') and 0x230000 <= pos < 0x260000: pool_rank = 0
                    elif 0x400000 <= pos < 0x420000: pool_rank = 2
                    elif 0x240000 <= pos < 0x280000: pool_rank = 3
                    else: pool_rank = 5
                refs = score_occurrence(entry)
                # Do not silently pick a random string from an unrelated resource
                # area. Such an occurrence is considered only with clear pointer
                # evidence; this was the main source of renames that did not show.
                effective_rank = pool_rank if pool_rank <= 3 else (4 if refs >= 2 else 6)
                return (effective_rank if prefer_main_pool else 0, -refs, pos)
            ranked = sorted(found, key=rank)
            best = ranked[0]
            evidence = rank(best)
            # Keep discovered strings visible in the tree even when the app cannot
            # prove their menu reference, but return that confidence to the UI so
            # unverified entries are read-only instead of silently writing the
            # wrong duplicate.
            return (best[0], best[1], best[2], evidence[0], score_occurrence(best))
        def find_label(aliases, setting_id=None):
            # Apply a previously saved custom title only when the exact offset in
            # this MMIRes still contains that title; this avoids leaking names to
            # unrelated firmware files.
            restored = saved_override(setting_id)
            if restored: return restored
            # Prefer an exact Hebrew label if present, then an exact English label.
            hebrew_aliases = [alias for alias in aliases if any('\u0590' <= ch <= '\u05ff' for ch in alias)]
            ordered_aliases = hebrew_aliases + [alias for alias in aliases if alias not in hebrew_aliases]
            for alias in ordered_aliases:
                found = pick_occurrence(alias)
                if found:
                    return {'title': found[1], 'offset': found[0], 'kind': found[2], 'source_alias': alias, 'setting_id': setting_id, 'source_pool_rank': found[3], 'source_ref_count': found[4], 'verified_source': (found[3] <= 3 or found[4] >= 2)}
            return None

        symbols = []
        seen_symbols = set()
        symbol_re = re.compile(rb'IMAGE_SECMENU_ICON_[A-Z0-9_]+')
        for match in symbol_re.finditer(mmi_res):
            symbol = match.group().decode('ascii', 'ignore')
            if symbol not in seen_symbols:
                seen_symbols.add(symbol)
                symbols.append({'symbol': symbol, 'offset': match.start(), 'resource_id': int.from_bytes(mmi_res[match.start()-8:match.start()-4], 'little') if match.start() >= 8 else None})
        symbol_by_name = {entry['symbol']: entry for entry in symbols}

        # Eight root categories, in the exact order requested from the handset:
        # System, Connectivity, Personalisation, Time & language, Security, STK,
        # Storage, VoLTE. Root labels are resolved from MMIRes. Child membership is
        # drawn from strings/resources found in the PAC; the remaining runtime menu
        # index table has not been fully decoded, so not every child relation can yet
        # be proven solely from the resource strings.
        category_specs = [
            {
                'key': 'SYSTEM', 'icon': '⚙', 'name_aliases': ['מערכת', 'System'], 'display_fallback': 'מערכת',
                'items': [
                    (['About', 'אודות'], 'ABOUT'),
                    (['Product info', 'Product information', 'מידע על המוצר'], 'PRODUCT_INFO'),
                    (['Online software update', 'עדכון תוכנה מקוון', 'בדוק לעדכונים', 'בדוק עדכונים'], 'UPDATE'),
                    (['Restore factory settings', 'שחזור הגדרות יצרן'], 'RESET'),
                    (['Send feedback', 'לשלוח משוב', 'משוב'], 'FEEDBACK'),
                    (['Battery & power', 'סוללה ועוצמה'], 'POWER_MANAGER'),
                    (['Battery status', 'מצב סוללה'], 'BATTERY_STATUS'),
                    (['Display settings', 'הגדרות תצוגה'], 'DISPLAY'),
                    (['Installed apps', 'אפליקציות מותקנות', "אפליקצ' מותקנות"], 'INSTALLED_APPS'),
                    (['Backlight', 'אור רקע'], 'BACKLIGHT'),
                    (['Font size', 'גודל גופן'], 'FONT_SIZE'),
                    (['Timeout', 'זמן קצוב'], 'DISPLAY_TIMEOUT'),
                ]
            },
            {
                'key': 'CONNECTIVITY', 'icon': '↔', 'name_aliases': ['קישוריות', 'Connectivity'], 'display_fallback': 'קישוריות',
                'items': [
                    (['Call settings', 'הגדרות שיחה', 'אפשרויות שיחה'], 'CALL_SETTINGS'),
                    (['Dual SIM', 'Dual SIM settings', 'אפשרויות SIM', 'הגדרות SIM'], 'DUAL_SIM'),
                    (['Bluetooth', 'בלוטות'], 'BT'),
                    (['Network settings', 'הגדרות רשת'], 'NET'),
                    (['Connection settings', 'הגדרות חיבור'], 'CONNECTION'),
                    (['Access points', 'נקודות גישה'], 'ACCESS_POINT'),
                    (['Data roaming', 'נדידת נתונים'], 'ROAMING'),
                    (['Select SIM', 'בחירת SIM'], 'SELECT_SIM'),
                    (['Call forwarding', 'העברת שיחות'], 'CALL_FORWARDING'),
                    (['Call barring', 'חסימת שיחה'], 'CALL_BARRING'),
                ]
            },
            {
                'key': 'PERSONALISATION', 'icon': '▣', 'name_aliases': ['התאמה אישית', 'Personalisation', 'Personalization'], 'display_fallback': 'התאמה אישית',
                'items': [
                    (['Welcome note', 'Welcome message', 'הודעת פתיחה'], 'WELCOME'),
                    (['Sounds', 'צלילים'], 'SOUNDS'),
                    (['Lock screen background', 'רקע מסך הנעילה'], 'LOCKSCREEN'),
                    (['Keypad', 'לוח מקשים'], 'KEYPAD'),
                    (['Vibration', 'רטט'], 'VIBRATION'),
                    (['Message notifications', 'התראות הודעות'], 'NOTIFICATIONS'),
                    (['Warnings', 'אזהרות'], 'WARNINGS'),
                    (['Wallpapers', 'רקעים'], 'WALLPAPER'),
                    (['Choose from gallery', 'בחר מגלריה'], 'CHOOSE_GALLERY'),
                    (['Keypad shortcuts', 'קיצורי דרך לוח המקשים'], 'SHORTCUT'),
                    (['Speed dial', 'חיוג מהיר'], 'SPEED_DIAL'),
                    (['Lock screen shortcuts', 'קיצורי דרך מסך הנעילה'], 'LOCKSCREEN_SHORTCUT'),
                    (['Right key', 'מקש ימיני'], 'RIGHT_KEY'),
                    (['Left key', 'מקש שמאלי'], 'LEFT_KEY'),
                    (['Background', 'רקע'], 'BACKGROUND'),
                ]
            },
            {
                'key': 'TIME_LANGUAGE', 'icon': '◷', 'name_aliases': ['זמן ושפה', 'Time & language', 'Time and language'], 'display_fallback': 'זמן ושפה',
                'items': [
                    (['Date and time', 'Date & time', 'תאריך ושעה'], 'TIMEDATE'),
                    (['Language', 'שפה'], 'LANGUAGE'),
                    (['Phone language', 'שפת הטלפון'], 'PHONE_LANGUAGE'),
                    (['Time zone', 'אזור זמן'], 'TIMEZONE'),
                    (['24-hour clock', 'שעון 24 שעות'], 'HOUR24'),
                    (['Set automatically', 'הגדרה אוטומטית'], 'TIME_AUTO'),
                ]
            },
            {
                'key': 'SECURITY', 'icon': '🔒', 'name_aliases': ['אבטחה', 'Security'], 'display_fallback': 'אבטחה',
                'items': [
                    (['Keyguard', 'נעילת מקשים'], 'KEYGUARD'),
                    (['Automatic keyguard', 'נעילת מקשים אוטו.', 'נעילת מקשים אוטומטית'], 'AUTO_KEYGUARD'),
                    (['Security code', 'קוד אבטחה'], 'SECURITY_CODE'),
                    (['PIN request', 'דרישת קוד PIN'], 'PIN_REQUEST'),
                    (['Change PIN', 'שינוי PIN', 'שינוי קוד PIN'], 'CHANGE_PIN'),
                    (['Call barring', 'חסימת שיחה'], 'CALL_BARRING_SECURITY'),
                ]
            },
            {
                'key': 'STK', 'icon': '▤', 'name_aliases': ['STK'], 'display_fallback': 'STK',
                'items': [
                    (['STK service', 'שירות STK'], 'STK_SERVICE'),
                    (['SIM toolkit', 'ערכת כלים של SIM'], 'SIM_TOOLKIT'),
                ]
            },
            {
                'key': 'STORAGE', 'icon': '▣', 'name_aliases': ['אחסון', 'Storage'], 'display_fallback': 'אחסון',
                'items': [
                    (['Phone storage', 'זיכרון הטלפון'], 'PHONE_STORAGE'),
                    (['Memory card', 'כרטיס זיכרון'], 'MEMORY_CARD'),
                    (['USB storage', 'אחסון USB'], 'USB_STORAGE'),
                    (['File manager', 'מנהל קבצים', 'קבצים'], 'FILE_MANAGER'),
                ]
            },
            {
                'key': 'VOLTE', 'icon': '▰', 'name_aliases': ['VoLTE'], 'display_fallback': 'VoLTE',
                'items': [
                    (['SIM 1'], 'VOLTE_SIM1'),
                    (['SIM 2'], 'VOLTE_SIM2'),
                    (['Select Mode', 'בחר מצב'], 'VOLTE_MODE'),
                    (['2G only', '2G בלבד'], 'VOLTE_2G'),
                    (['4G only', '4G בלבד'], 'VOLTE_4G'),
                    (['4G/2G auto', '4G/2G אוטומטי'], 'VOLTE_AUTO'),
                    (['Enable 4.5G', 'אפשר 4.5 גרם'], 'VOLTE_ENABLE'),
                    (['Disable 4.5G', 'השבת 4.5 גרם'], 'VOLTE_DISABLE'),
                    (['LTE only', 'LTE בלבד'], 'VOLTE_LTE'),
                ]
            },
        ]

        # Resource symbol-name lookup is retained to show evidence for child rows.
        # These symbols are not used to infer the Settings-root categories/order.
        child_symbol_aliases = {
            'UPDATE': 'IMAGE_SECMENU_ICON_SET_UPDATE',
            'ABOUT': 'IMAGE_SECMENU_ICON_SET_ABOUT',
            'PRODUCT_INFO': 'IMAGE_SECMENU_ICON_SET_PRODUCT_INFO',
            'POWER_MANAGER': 'IMAGE_SECMENU_ICON_POWER_MANAGER',
            'BATTERY_STATUS': 'IMAGE_SECMENU_ICON_BATTERY_STATUS',
            'PHONE_STORAGE': 'IMAGE_SECMENU_ICON_STORAGE',
            'DISPLAY': 'IMAGE_SECMENU_ICON_SET_DISPLAY',
            'RESET': 'IMAGE_SECMENU_ICON_SET_RESET',
            'FEEDBACK': 'IMAGE_SECMENU_ICON_SET_FEEDBACK',
            'BT': 'IMAGE_SECMENU_ICON_LINKSET_BT',
            'NET': 'IMAGE_SECMENU_ICON_LINKSET_NET',
            'WELCOME': 'IMAGE_SECMENU_ICON_SET_WELCOME',
            'SOUNDS': 'IMAGE_SECMENU_ICON_SET_SOUNDS',
            'KEYPAD': 'IMAGE_SECMENU_ICON_SET_KEYPAD',
            'SHORTCUT': 'IMAGE_SECMENU_ICON_SET_SHORTCUT',
            'LOCKSCREEN_SHORTCUT': 'IMAGE_SECMENU_ICON_SET_LOCKSCREEN_SHORTCUT',
            'STK_SERVICE': 'IMAGE_SECMENU_ICON_TOOL_STK',
        }
        groups = []
        for spec in category_specs:
            key = spec['key']
            title_info = find_label(spec['name_aliases'], 'category:' + key)
            # Keep all eight root categories in the observed handset order. A label
            # without a verified MMIRes occurrence is visibly marked and cannot be
            # renamed into the firmware until its actual resource is located.
            if not title_info:
                title_info = {'title': spec.get('display_fallback', key), 'offset': None,
                              'kind': None, 'source_alias': 'קטגוריית ממשק; מקור טקסט לא נמצא',
                              'setting_id': 'category:' + key}
            group = {
                'key': key, 'setting_id': 'category:' + key, 'icon': spec['icon'],
                'name': title_info['title'], 'name_offset': title_info['offset'],
                'name_kind': title_info['kind'], 'verified_source': title_info.get('verified_source', False),
                'source_pool_rank': title_info.get('source_pool_rank'), 'source_ref_count': title_info.get('source_ref_count', 0),
                'symbol_offset': None, 'symbol': '',
                'items': [], 'order_basis': 'user-provided-device-root-order'
            }
            seen = set()
            for aliases, child_id in spec['items']:
                setting_id = 'item:' + key + ':' + child_id
                info = find_label(aliases, setting_id)
                if not info:
                    continue
                ident = (info['offset'], label_key(info['title']))
                if ident in seen or (group.get('name_offset') is not None and info['offset'] == group.get('name_offset')):
                    continue
                seen.add(ident)
                sym_name = child_symbol_aliases.get(child_id, '')
                sym = symbol_by_name.get(sym_name) if sym_name else None
                info['symbol'] = sym_name if sym else ''
                info['symbol_offset'] = sym['offset'] if sym else None
                info['setting_id'] = setting_id
                info['relationship'] = 'resource symbol' if sym else 'firmware label; category membership reconstructed'
                group['items'].append(info)
            groups.append(group)

        # Build a nested view from parent labels present in the actual PAC. The
        # root order is supplied by the user; child relationships below are
        # reconstructed from labels in MMIRes and remain explicitly marked as such.
        def item_code(item):
            return (item.get('setting_id') or '').rsplit(':', 1)[-1]

        def move_children(group_key, parent_code, child_codes):
            group = next((g for g in groups if g['key'] == group_key), None)
            if not group:
                return
            parent = next((it for it in group['items'] if item_code(it) == parent_code), None)
            if parent is None:
                return
            moved = [it for it in group['items'] if item_code(it) in set(child_codes)]
            if not moved:
                return
            parent.setdefault('children', []).extend(moved)
            group['items'] = [it for it in group['items'] if item_code(it) not in set(child_codes)]

        move_children('SYSTEM', 'DISPLAY', ['BACKLIGHT', 'FONT_SIZE', 'DISPLAY_TIMEOUT'])
        move_children('CONNECTIVITY', 'CALL_SETTINGS', ['DUAL_SIM', 'SELECT_SIM', 'CALL_FORWARDING', 'CALL_BARRING'])
        move_children('PERSONALISATION', 'WALLPAPER', ['BACKGROUND', 'CHOOSE_GALLERY'])
        move_children('PERSONALISATION', 'SHORTCUT', ['RIGHT_KEY', 'LEFT_KEY'])
        move_children('TIME_LANGUAGE', 'TIMEDATE', ['TIMEZONE', 'HOUR24', 'TIME_AUTO'])
        move_children('TIME_LANGUAGE', 'LANGUAGE', ['PHONE_LANGUAGE'])
        move_children('SECURITY', 'KEYGUARD', ['AUTO_KEYGUARD'])
        move_children('VOLTE', 'VOLTE_MODE', ['VOLTE_2G', 'VOLTE_4G', 'VOLTE_AUTO', 'VOLTE_LTE'])

        # Utility functions operate on every depth so edits also refresh nested rows.
        def iter_all_items(items, prefix=()):
            for i, item in enumerate(items):
                path = prefix + (i,)
                yield item, path
                yield from iter_all_items(item.get('children', []), path)

        def item_at_path(group, path):
            if not path:
                raise ValueError('נתיב הגדרה ריק')
            item = group['items'][path[0]]
            for i in path[1:]:
                item = item['children'][i]
            return item

        if not groups:
            messagebox.showinfo('הגדרות מהקושחה', 'נמצאו משאבי MMIRes, אך לא נמצאו כותרות הגדרות בקושחה הזאת.', parent=self)
            return

        win = tk.Toplevel(self)
        win.title('תפריטי הגדרות Nokia 225 — v31')
        win.geometry('880x640'); win.minsize(760, 520); win.configure(bg='#e8edf4'); win.transient(self)
        header = tk.Frame(win, bg='#173b63', height=58); header.pack(fill='x'); header.pack_propagate(False)
        tk.Label(header, text='NOKIA', bg='#173b63', fg='#d7e9f8', font=('Segoe UI', 10, 'bold')).pack(side='left', padx=(18, 8))
        tk.Label(header, text='הגדרות המכשיר', bg='#173b63', fg='white', font=('Segoe UI', 16, 'bold')).pack(side='left')
        tk.Label(header, text=f'MMIRes • {len(groups)} קטגוריות', bg='#173b63', fg='#b8d2e8', font=('Segoe UI', 9)).pack(side='right', padx=16)
        notice = tk.Label(win, text='שמונה קטגוריות ראשיות מוצגות בסדר שמסרת מהמכשיר. שמות נטענים ממשאבי MMIRes; פריטי משנה מקובצים לפי תוויות שנמצאו, אך טבלת קשרי התפריט בזמן ריצה עדיין לא פוענחה במלואה. פריט ללא הפניה מאומתת מוצג לקריאה בלבד. שינוי שם מתבצע בקושחה: בשדה קיים או בהעתקת מחרוזת והפניית מצביעים; אם לא ניתן להוכיח הפניות בטוחות, השינוי נדחה. לשמירת שינוי בקושחה יש ללחוץ על „שמור PAC חדש”.', bg='#fff7ed', fg='#9a3412', font=('Segoe UI', 9), wraplength=840, justify='right', anchor='e', padx=12, pady=8)
        notice.pack(fill='x', padx=12, pady=(10, 0))
        toolbar = tk.Frame(win, bg='#e8edf4'); toolbar.pack(fill='x', padx=12, pady=(7, 0))
        def save_settings_pac():
            self._last_save_success = False
            self.save()
            if getattr(self, '_last_save_success', False):
                try: win.destroy()
                except Exception: pass
        tk.Button(toolbar, text='💾 שמור PAC חדש…', command=save_settings_pac, bg='#047857', fg='white', activebackground='#065f46', activeforeground='white', relief='flat', padx=12, pady=6, font=('Segoe UI', 9, 'bold')).pack(side='left')
        tk.Label(toolbar, text='שינוי שם נכתב לקושחה או נדחה אם אין דרך בטוחה לעדכן את משאביה — לא נשמר שם תצוגה מדומה.', bg='#e8edf4', fg='#475569', font=('Segoe UI', 9)).pack(side='right')
        body = tk.Frame(win, bg='#e8edf4'); body.pack(fill='both', expand=True, padx=12, pady=10)
        left = tk.Frame(body, bg='white', highlightbackground='#cbd5e1', highlightthickness=1, width=260); left.pack(side='left', fill='y'); left.pack_propagate(False)
        tk.Label(left, text='קטגוריות הגדרות בסדר המקורי', bg='#f4f7fb', fg='#52657b', font=('Segoe UI', 10, 'bold'), anchor='w', padx=12, pady=10).pack(fill='x')
        nav = tk.Frame(left, bg='white'); nav.pack(fill='both', expand=True, padx=7, pady=7)
        right = tk.Frame(body, bg='#d5dde8'); right.pack(side='right', fill='both', expand=True, padx=(12, 0))
        phone = tk.Frame(right, bg='#f8fafc', highlightbackground='#334155', highlightthickness=3); phone.place(relx=.5, rely=.5, anchor='center', relwidth=.88, relheight=.93)
        tk.Label(phone, text='●  NOKIA 225', bg='#e6edf5', fg='#334155', font=('Segoe UI', 8, 'bold'), anchor='w', padx=8, pady=5).pack(fill='x')
        screen_title = tk.Label(phone, text='הגדרות', bg='#2463a6', fg='white', font=('Segoe UI', 12, 'bold'), anchor='w', padx=10, pady=8); screen_title.pack(fill='x')
        screen = tk.Frame(phone, bg='white'); screen.pack(fill='both', expand=True)
        soft = tk.Frame(phone, bg='#e6edf5'); soft.pack(fill='x')
        soft_left = tk.Label(soft, text='בחירה', bg='#e6edf5', fg='#334155', font=('Segoe UI', 8), anchor='w', padx=8, pady=5); soft_left.pack(side='left')
        soft_right = tk.Label(soft, text='חזרה', bg='#e6edf5', fg='#334155', font=('Segoe UI', 8), anchor='e', padx=8, pady=5); soft_right.pack(side='right')
        state = {'group': None, 'item': None}

        def string_record_span(data, offset, kind):
            """Return original encoded record span, rounded to its 4-byte allocation."""
            if kind == 'UTF-16LE resource string':
                if offset + 4 > len(data) or data[offset:offset+2] != b'\x80\x00':
                    raise ValueError('מבנה רשומת UTF-16LE לא תקין.')
                ln = int.from_bytes(data[offset+2:offset+4], 'little')
                if ln < 2 or ln % 2 or offset + 4 + ln > len(data):
                    raise ValueError('אורך רשומת UTF-16LE לא תקין.')
                return ((4 + ln + 3) // 4) * 4
            end = data.find(b'\x00', offset, min(len(data), offset + 4097))
            if end < 0:
                raise ValueError('לא נמצא סוף למחרוזת ASCII.')
            return end - offset + 1

        def preferred_pointer_base(offset):
            # Relative text references are based on the containing 64-KiB bank.
            # Do not merge adjacent banks (for example 0x410000 and 0x400000, or
            # 0x270000 and 0x260000), otherwise edited long strings can redirect
            # pointers to unrelated bytes.
            return (int(offset) // 0x10000) * 0x10000

        def find_pointer_slots(data, offset, span, preferred_base):
            """Find only exact relative pointers to the record or its payload.

            Earlier code searched every byte inside the string and guessed dozens
            of possible 64-KiB bases. That could mistake unrelated integers for
            pointers and damage unrelated firmware data. This version accepts only
            exact pointers to the record header or payload start, relative to the
            resource bank's known base, and only aligned 32-bit slots.
            """
            candidates = {int(offset) - int(preferred_base): 0,
                          int(offset) + (4 if kind_is_utf16(data, offset) else 0) - int(preferred_base):
                              (4 if kind_is_utf16(data, offset) else 0)}
            selected = {}
            base_counts = {int(preferred_base): 0}
            n = len(data)
            for value, delta in candidates.items():
                if value < 0 or value > 0xFFFFFFFF:
                    continue
                needle = struct.pack('<I', value)
                pos = 0
                while True:
                    pos = data.find(needle, pos)
                    if pos < 0:
                        break
                    if pos % 4 == 0 and not (pos < offset + span and pos + 4 > offset):
                        selected[pos] = (int(preferred_base), delta)
                        base_counts[int(preferred_base)] += 1
                    pos += 1
            ordered = sorted(selected)
            for i in range(1, len(ordered)):
                if ordered[i] < ordered[i-1] + 4:
                    raise ValueError('נמצאו הפניות בינאריות חופפות; אי אפשר להזיז את המחרוזת בבטחה.')
            # Repeated exact references provide stronger evidence than a single
            # coincidental integer. A single aligned reference is retained only
            # when it lives in the metadata region associated with this bank.
            count = len(selected)
            if count == 1:
                pos = next(iter(selected))
                bank = int(preferred_base)
                plausible = ((bank == 0x440000 and 0x440000 <= pos < 0x520000) or
                             (0x400000 <= bank < 0x440000 and (0x400000 <= pos < 0x420000 or 0x240000 <= pos < 0x280000 or 0x440000 <= pos < 0x520000)) or
                             (0x200000 <= bank < 0x280000 and 0x200000 <= pos < 0x520000) or
                             (0x500000 <= bank < 0x560000 and 0x440000 <= pos < 0x560000))
                if not plausible:
                    selected = {}
                    base_counts[bank] = 0
            return selected, base_counts

        def kind_is_utf16(data, offset):
            return offset + 2 <= len(data) and data[offset:offset+2] == b'\x80\x00'

        def relocate_string(data, offset, kind, new_title):
            """Refuse unsafe growth until the firmware pointer table is decoded.

            The previous implementation scanned all of MMIRes for DWORDs that
            numerically resembled relative pointers. That is not proof that those
            words are pointers; rewriting a coincidental match can corrupt the
            MMIRes resource graph and produce a PAC that passes outer CRC checks
            but fails in the handset. In-place edits that fit the original field
            are still supported by rename_entry. Longer names are rejected.
            """
            raise ValueError(
                'השם החדש ארוך מהשדה המקורי. לא ניתן להעביר את המחרוזת בבטחה: '
                'טבלת ההפניות הפעילה של הקושחה עדיין לא פוענחה במלואה. '
                'לא בוצע שינוי. בחר שם קצר יותר שמתאים לשדה הקיים.'
            )

        def pool_bounds(offset):
            # Limit duplicate edits to the relevant localized UI/resource bank.
            if 0x445000 <= offset < 0x447500: return (0x445000, 0x447500)
            if 0x409000 <= offset < 0x40C000: return (0x409000, 0x40C000)
            if 0x413000 <= offset < 0x416000: return (0x413000, 0x416000)
            if 0x230000 <= offset < 0x240000: return (0x230000, 0x240000)
            if 0x240000 <= offset < 0x280000: return (0x240000, 0x280000)
            if 0x400000 <= offset < 0x420000: return (0x400000, 0x420000)
            if 0x480000 <= offset < 0x4C0000: return (0x480000, 0x4C0000)
            if 0x500000 <= offset < 0x560000: return (0x500000, 0x560000)
            start = (offset // 0x10000) * 0x10000
            return (start, min(len(mmi_res), start + 0x10000))

        def rename_entry(entry, is_group=False, group_idx=None, item_path=None):
            nonlocal mmi_res
            title = entry.get('name', '') if is_group else entry.get('title', '')
            offset = entry.get('name_offset') if is_group else entry.get('offset')
            kind = entry.get('name_kind') if is_group else entry.get('kind')
            setting_id = entry.get('setting_id')
            if offset is None or not kind or not setting_id:
                messagebox.showwarning('שינוי שם', 'לא נמצא משאב טקסט שניתן לעריכה עבור הפריט הזה. לא בוצע שינוי.', parent=win)
                return
            if not entry.get('verified_source', False):
                messagebox.showwarning('שינוי שם', 'נמצאה מחרוזת מתאימה, אך לא נמצאה הוכחה מספקת שהיא ההפניה הפעילה של פריט זה בתפריט. כדי למנוע שינוי של טקסט לא קשור, העריכה חסומה עד לפענוח ההפניה בקושחה.', parent=win)
                return
            new_title = simpledialog.askstring('שינוי שם הגדרה', 'הזן שם חדש. אם אין מספיק מקום, התוכנה תזיז את משאב הטקסט רק כאשר נמצאו הפניות מדויקות. אם אין אפשרות בטוחה, השינוי יידחה.\n\nשם נוכחי: ' + title, initialvalue=title, parent=win)
            if new_title is None: return
            new_title = clean_label(new_title)
            if not new_title or any(ord(ch) < 32 for ch in new_title):
                messagebox.showwarning('שינוי שם', 'השם אינו יכול להיות ריק או להכיל תווי בקרה.', parent=win); return
            if new_title == title: return
            off = int(offset)
            current_actual = read_label_at(off, kind)
            if current_actual is None:
                messagebox.showerror('שינוי שם', 'לא הצלחתי לאמת את מחרוזת המקור ב-offset שנשמר. לא בוצע שינוי.', parent=win); return

            # Change only the physical record selected for this setting. Matching
            # text elsewhere can be shared by unrelated menu items.
            targets = [(off, kind)]
            work = bytes(mmi_res)
            moved_offsets = {}
            capacities = {}
            old_titles = {}
            try:
                for target_off, target_kind in targets:
                    actual = read_label_at(target_off, target_kind)
                    if actual != current_actual:
                        continue
                    old_titles[target_off] = actual
                    if target_kind == 'UTF-16LE resource string':
                        if target_off + 4 > len(work) or work[target_off:target_off+2] != b'\x80\x00':
                            raise ValueError('מבנה רשומת UTF-16LE השתנה; לא בוצע שינוי.')
                        byte_len = int.from_bytes(work[target_off+2:target_off+4], 'little')
                        if byte_len < 2 or byte_len % 2 or target_off + 4 + byte_len > len(work):
                            raise ValueError('אורך רשומת UTF-16LE אינו תקין.')
                        encoded = new_title.encode('utf-16le')
                        capacities[target_off] = byte_len
                        if len(encoded) <= byte_len:
                            b = bytearray(work)
                            b[target_off+4:target_off+4+byte_len] = encoded + b'\x00' * (byte_len-len(encoded))
                            work = bytes(b)
                            moved_offsets[target_off] = target_off
                        else:
                            changed, new_off, capacity, redirected, banks = relocate_string(work, target_off, target_kind, new_title)
                            work = changed
                            moved_offsets[target_off] = new_off
                            capacities[target_off] = capacity
                    elif target_kind == 'ASCII resource string':
                        end_pos = work.find(b'\x00', target_off, min(len(work), target_off+4097))
                        if end_pos < 0: raise ValueError('לא נמצא סוף בטוח למחרוזת ASCII.')
                        old_len = end_pos - target_off
                        try: encoded = new_title.encode('ascii')
                        except UnicodeEncodeError:
                            raise ValueError('המשאב המקורי הוא ASCII. כדי לכתוב עברית צריך למצוא את מחרוזת התרגום המתאימה; לא שונה הקובץ.')
                        capacities[target_off] = old_len
                        if len(encoded) <= old_len:
                            b = bytearray(work)
                            b[target_off:target_off+old_len] = encoded + b'\x00' * (old_len-len(encoded))
                            work = bytes(b)
                            moved_offsets[target_off] = target_off
                        else:
                            changed, new_off, capacity, redirected, banks = relocate_string(work, target_off, target_kind, new_title)
                            work = changed
                            moved_offsets[target_off] = new_off
                            capacities[target_off] = capacity
                    else:
                        raise ValueError('קידוד מחרוזת זה אינו נתמך לעריכה בטוחה.')
            except (ValueError, UnicodeEncodeError, struct.error) as exc:
                messagebox.showerror('שינוי שם לא בוצע', str(exc) + '\n\nלא נשמר כינוי תצוגה בלבד ולא בוצע שינוי חלקי.', parent=win)
                return

            if not moved_offsets:
                messagebox.showerror('שינוי שם', 'לא נמצאה רשומת טקסט ניתנת לשינוי במאגר הנכון. לא בוצע שינוי.', parent=win)
                return
            mmi_res = bytes(work)
            mmi_entry.data = mmi_res
            mmi_entry.changed = True

            # Update every view of the changed physical records, including nested
            # items and intentional clones (e.g. per-SIM VoLTE path).
            changed_ids = set()
            for g in groups:
                if g.get('name_offset') in moved_offsets:
                    old = g['name_offset']; g['name_offset'] = moved_offsets[old]; g['name'] = new_title; g['name_kind'] = kind; g['verified_source'] = True
                    changed_ids.add(g.get('setting_id'))
                for it, path in iter_all_items(g.get('items', [])):
                    if it.get('offset') in moved_offsets:
                        old = it['offset']; it['offset'] = moved_offsets[old]; it['title'] = new_title; it['verified_source'] = True
                        changed_ids.add(it.get('setting_id'))
            if is_group:
                entry['name'] = new_title
                entry['name_offset'] = moved_offsets.get(off, off)
                entry['name_kind'] = kind
                entry['verified_source'] = True
            else:
                entry['title'] = new_title
                entry['offset'] = moved_offsets.get(off, off)
                entry['kind'] = kind
                entry['verified_source'] = True
                changed_ids.add(setting_id)

            # Re-store each updated menu ID under this MMIRes generation. Existing
            # pre-v31 sidecars are intentionally not trusted because they may have
            # recorded an unreferenced duplicate string.
            for g in groups:
                if g.get('name_offset') is not None and g.get('setting_id') in changed_ids:
                    ident = g['setting_id']; pos = g['name_offset']; k = g.get('name_kind')
                    setting_name_overrides[f'{len(mmi_res)}:{ident}'] = {
                        'title': g['name'], 'offset': pos, 'kind': k,
                        'firmware_applied': True, 'editor_schema': 31,
                        'verified_firmware_ref': True, 'original': current_actual
                    }
                for it, path in iter_all_items(g.get('items', [])):
                    if it.get('setting_id') in changed_ids and it.get('offset') is not None:
                        setting_name_overrides[f'{len(mmi_res)}:{it["setting_id"]}'] = {
                            'title': it['title'], 'offset': it['offset'], 'kind': it.get('kind'),
                            'firmware_applied': True, 'editor_schema': 31,
                            'verified_firmware_ref': True, 'original': current_actual
                        }
            try:
                rename_db_path.write_text(json.dumps({'entries': setting_name_overrides}, ensure_ascii=False, indent=2), encoding='utf-8')
            except Exception as e:
                messagebox.showwarning('מפת שמות', f'השינוי נכתב לזיכרון הקושחה, אך מפת השמות המקומית לא נשמרה.\n{e}', parent=win)

            self.setstatus(f'נכתבו {len(moved_offsets)} מופעי טקסט בתוך MMIRes: {title} → {new_title}. לחץ „שמור PAC חדש” כדי לכתוב את השינוי לקובץ PAC.')
            messagebox.showinfo('שינוי שם בקושחה', f'השם נכתב למשאב/י MMIRes.\n\n{title} → {new_title}\nמופעי טקסט ששונו: {len(moved_offsets)}.\n\nהשינוי ייכלל בקובץ קושחה רק לאחר „שמור PAC חדש”. אחרי הצריבה יש לבדוק במכשיר שהכיתוב הוצג כמצופה.', parent=win)
            if is_group and group_idx is not None:
                render_group(group_idx)
            elif group_idx is not None and item_path:
                render_item(group_idx, item_path)

        def clear_screen():
            for child in screen.winfo_children(): child.destroy()
        def render_home():
            state.update(group=None, item=None); screen_title.config(text='הגדרות'); clear_screen()
            tk.Label(screen, text='הגדרות — קטגוריות ראשיות לפי מדריך Nokia 225', bg='white', fg='#64748b', font=('Segoe UI', 9), anchor='w', padx=10, pady=8).pack(fill='x')
            for idx, group in enumerate(groups):
                row = tk.Frame(screen, bg='white'); row.pack(fill='x')
                tk.Label(row, text=group['icon'], bg='white', fg='#2463a6', font=('Segoe UI', 13, 'bold'), width=3).pack(side='left', padx=(5, 0), pady=5)
                tk.Button(row, text=group['name'], anchor='w', bg='white', fg='#1f2937', activebackground='#dbeafe', relief='flat', bd=0, font=('Segoe UI', 10), command=lambda i=idx: render_group(i)).pack(side='left', fill='x', expand=True, padx=4, pady=2)
                tk.Label(row, text='›', bg='white', fg='#64748b', font=('Segoe UI', 13)).pack(side='right', padx=8)
                tk.Frame(screen, bg='#e5eaf1', height=1).pack(fill='x', padx=8)
            soft_left.config(text='בחירה'); soft_right.config(text='יציאה')
        def render_group(idx):
            group = groups[idx]; state.update(group=idx, item=None); screen_title.config(text=group['name']); clear_screen()
            tk.Button(screen, text='← חזרה לקטגוריות', anchor='w', bg='#f1f5f9', fg='#2463a6', relief='flat', bd=0, font=('Segoe UI', 9), command=render_home).pack(fill='x', padx=6, pady=(6, 4))
            tk.Button(screen, text='✎ שנה שם לקטגוריה הזאת', anchor='w', bg='#eff6ff', fg='#1d4ed8', activebackground='#dbeafe', relief='flat', bd=0, font=('Segoe UI', 9, 'bold'), command=lambda i=idx: rename_entry(groups[i], True, i)).pack(fill='x', padx=6, pady=(0, 5))
            if not group['items']:
                tk.Label(screen, text='לא נמצאו מחרוזות משנה שניתן לשייך בבטחה לקטגוריה זו.', bg='white', fg='#64748b', font=('Segoe UI', 9), wraplength=340, justify='right', padx=12, pady=14).pack(fill='x')
            for item_idx, item in enumerate(group['items']):
                row = tk.Frame(screen, bg='white'); row.pack(fill='x')
                suffix = '   ›' if item.get('children') else ''
