    def setstatus(self,s):self.status.set(s);self.update_idletasks()
    def _progress_window(self, title, text='טוען...'):
        """Animated loading dialog with bouncing dots and progress information."""
        w=tk.Toplevel(self); w.title(title); w.geometry('430x250'); w.resizable(False,False)
        w.configure(bg='#eaf0fb'); w.transient(self); w.grab_set()
        try:
            w.update_idletasks()
            x=max(0,self.winfo_rootx()+(self.winfo_width()-430)//2)
            y=max(0,self.winfo_rooty()+(self.winfo_height()-250)//2)
            w.geometry(f'430x250+{x}+{y}')
        except Exception: pass
        card=tk.Frame(w,bg='#ffffff',highlightbackground='#d9e2f2',highlightthickness=1)
        card.pack(fill='both',expand=True,padx=14,pady=14)
        tk.Label(card,text='NOKIA 225  •  PAC STUDIO',bg='#ffffff',fg='#7c8ba1',font=('Segoe UI',8,'bold')).pack(pady=(16,2))
        tk.Label(card,text='טוען',bg='#ffffff',fg='#172033',font=('Segoe UI',22,'bold')).pack()
        label=tk.Label(card,text=text,bg='#ffffff',fg='#64748b',font=('Segoe UI',10),wraplength=380)
        label.pack(pady=(1,2))
        cv=tk.Canvas(card,width=180,height=43,bg='#ffffff',highlightthickness=0); cv.pack(pady=(0,3))
        colors=['#2563eb'] * 5; dots=[]
        for i,col in enumerate(colors): dots.append(cv.create_oval(0,0,0,0,fill=col,outline=''))
        bar_bg=tk.Frame(card,bg='#e8eef8',height=5); bar_bg.pack(fill='x',padx=28,pady=(2,5)); bar_bg.pack_propagate(False)
        bar=tk.Frame(bar_bg,bg='#4f7cff',height=5,width=1); bar.place(x=0,y=0,relheight=1)
        pctlbl=tk.Label(card,text='0%',bg='#ffffff',fg='#94a3b8',font=('Segoe UI',8)); pctlbl.pack(pady=(0,8))
        state={'alive':True,'frame':0,'value':0.0,'last':0.0}
        def animate():
            if not state['alive'] or not w.winfo_exists(): return
            state['frame']+=1; f=state['frame']
            for i,item in enumerate(dots):
                x=24+i*33; y=22-8*max(0,1-abs(((f/3+i*2)%12)-6)/3)
                cv.coords(item,x-6,y-6,x+6,y+6)
            w.after(45,animate)
        def setp(value,msg=None):
            value=max(0,min(100,float(value))); now=time.monotonic()
            if value < 100 and value-state['value'] < .5 and now-state['last'] < .05: return
            state['value']=value; state['last']=now
            if msg is not None: label.config(text=msg)
            pctlbl.config(text=f'{value:.0f}%')
            try: bar.place_configure(width=max(1,int(bar_bg.winfo_width()*value/100)))
            except Exception: pass
            w.update_idletasks(); w.update()
        def close():
            state['alive']=False
            try: w.destroy()
            except Exception: pass
        w.protocol('WM_DELETE_WINDOW', lambda: None)
        w.update_idletasks(); animate()
        return w,setp

    def _open_standalone_image(self, path):
        try:
            raw=Path(path).read_bytes()
            im, decoder=self._display_decode_image(raw, None)
            if im is None:
                raise ValueError('לא הצלחתי לפענח את קובץ התמונה: '+decoder)
            fmt=(Image.open(io.BytesIO(raw)).format or Path(path).suffix.lstrip('.')).upper()
            if fmt=='JPG': fmt='JPEG'
            self.data=raw; self.path=Path(path); self._standalone_image=True; self._structural_dirty=False
            self.rs=[Res(1,fmt,0,len(raw),im.width,im.height,False,raw,Path(path).name,'קובץ תמונה',True)]
            self.sel=self.rs[0]; self.deep_done=True; self.mode='files'
            self.count.config(text=f'קובץ תמונה יחיד  •  {fmt}  •  {im.width}×{im.height}  •  {len(raw):,} bytes')
            self.filter(); self.tree.selection_set('1'); self.tree.see('1'); self.select()
            self.setstatus(f'נפתחה תמונה: {Path(path).name} ({fmt})')
        except Exception as e:
            messagebox.showerror('פתיחת תמונה',f'לא ניתן לפתוח את הקובץ.\n\n{e}')

    def _scan_pac_background(self, setp):
        result_queue=queue.Queue()
        def worker():
            try: result_queue.put(('ok',Scanner(self.data).scan(deep=False)))
            except Exception as exc: result_queue.put(('error',exc))
        thread=threading.Thread(target=worker,name='PAC-table-scan',daemon=True)
        thread.start(); result=None; failure=None
        setp(72,'מנתח טבלת PAC...')
        while thread.is_alive() or not result_queue.empty():
            try:
                kind,value=result_queue.get(timeout=0.025)
                if kind=='ok': result=value
                else: failure=value
            except queue.Empty: pass
            try: self.update()
            except Exception: pass
        if failure: raise failure
        self.rs=result or []; self.deep_done=False
        self.filter()
        files=sum(1 for r in self.rs if r.is_file); embedded=len(self.rs)-files
        self.count.config(text=f'{files} קבצי PAC  •  {embedded} משאבים פנימיים  •  {len(self.rs)} פריטים')

    def _read_file_progress(self,path,setp):
        total=os.path.getsize(path); got=0; chunks=[]
        with open(path,'rb') as f:
            while True:
                b=f.read(4*1024*1024)
                if not b: break
                chunks.append(b); got+=len(b); setp((got/total)*65 if total else 65,f'קורא PAC... {got:,} / {total:,} bytes')
        return b''.join(chunks)

    def open(self):
        p=filedialog.askopenfilename(filetypes=[('PAC וקובצי תמונה','*.pac *.jpg *.jpeg *.bmp *.png *.gif *.tif *.tiff *.webp'),('קובצי PAC','*.pac'),('תמונות','*.jpg *.jpeg *.bmp *.png *.gif *.tif *.tiff *.webp'),('כל הקבצים','*.*')]);
        if not p:return
        if any(r.changed for r in self.rs) and not messagebox.askyesno('אישור','יש שינויים שלא נשמרו. פתיחת קובץ חדש תמחק אותם. להמשיך?'):return
        if Path(p).suffix.lower() != '.pac':
            self._open_standalone_image(p)
            return
        self._standalone_image=False
        pw=None
        try:
            pw,setp=self._progress_window('פתיחת PAC','מתכונן...')
            self.path=Path(p); self._structural_dirty=False; self._time_lang=''; setp(2,'פותח את קובץ ה-PAC...')
            self.data=self._read_file_progress(self.path,setp)
            self.rs=[]
            setp(70,'מנתח את מבנה ה-PAC...'); self._scan_pac_background(setp); setp(96,'מסיים טעינה ומרענן את הממשק...'); self.update_idletasks(); setp(100,'ה-PAC נטען בהצלחה')
            pw.after(180,pw.destroy)
        except Exception as e:
            if pw:
                try: pw.destroy()
                except Exception: pass
            messagebox.showerror('שגיאה',str(e))
    def scan(self, deep=True):
        if not self.data:return
        if any(r.changed for r in self.rs) and not messagebox.askyesno('אישור','יש שינויים שלא נשמרו. סריקה מחדש תמחק אותם. להמשיך?'):return
        self.rs=Scanner(self.data).scan(deep=deep);self.deep_done=deep;self.filter();files=sum(1 for r in self.rs if r.is_file); embedded=len(self.rs)-files; self.count.config(text=f'{files} קבצי PAC  •  {embedded} משאבים פנימיים  •  {len(self.rs)} פריטים');self.setstatus('הסריקה הסתיימה — כל טבלת ה-PAC נטענה')
    def setmode(self,mode):
        if not self.data:
            return messagebox.showwarning('PAC','פתח קובץ PAC קודם')
        if mode in ('images','media') and not self.deep_done:
            loadwin,loadp=self._progress_window('טוען מדיה','סורק תמונות וקובצי מדיה...')
            try: self.deep_scan_all(loadp)
            finally:
                try: loadwin.destroy()
                except Exception: pass
        self.mode=mode
        self.filter()
        if mode=='images': self.show_gallery()
        elif mode=='media': self.show_media_browser()
        labels={'files':'מציג את כל המחיצות והרשומות מתוך ה-PAC','images':'מציג את כל התמונות והאייקונים שנמצאו בתוך קבצי ה-PAC','media':'מציג את כל המדיה והצלילים שנמצאו בתוך קבצי ה-PAC'}
        self.setstatus(labels[mode])

