        if hasattr(self,'gallery') and self.gallery.winfo_exists():
            self.gallery.lift(); return
        items=[r for r in self.rs if (r.kind in IMG or (not r.is_file and ('IMAGE' in (r.name or '').upper() or 'ICON' in (r.name or '').upper() or 'BG' in (r.name or '').upper()))) and not r.is_file]
        if not items: return messagebox.showinfo('תמונות','לא נמצאו משאבי תמונה')
