    def play_resource(self,r):
        self.tree.selection_set(str(r.idx)); self.tree.see(str(r.idx)); self.sel=r; self.play()

    def deep_scan_all(self, progress=None):
        snapshot_data=self.data
        current=self.rs[:]
        existing={(r.off,r.size,r.kind) for r in current if not r.is_file}
        files=[r for r in current if r.is_file and r.size and r.off>=0]
        messages=queue.Queue()
        def worker():
            try:
                sc=Scanner(snapshot_data); added=[]
                for fi,f in enumerate(files):
                    messages.put(('progress',(fi/max(1,len(files)))*90,f'סורק משאבים... {fi+1} / {len(files)}'))
                    try: sub=sc.scan_range(f.off,f.size,f.name or f.label)
                    except Exception: sub=[]
                    for r in sub:
                        key=(r.off,r.size,r.kind)
                        if key in existing: continue
                        r.name=f'{r.kind} @ 0x{r.off:08X}'
                        existing.add(key); added.append(r)
                messages.put(('done',added,None))
            except Exception as exc:
                messages.put(('error',exc,None))
        thread=threading.Thread(target=worker,name='PAC-deep-scan',daemon=True)
        thread.start(); added=None; failure=None
        while thread.is_alive() or not messages.empty():
            try:
                kind,value,msg=messages.get(timeout=0.025)
                if kind=='progress' and progress: progress(value,msg)
                elif kind=='done': added=value
                elif kind=='error': failure=value
            except queue.Empty: pass
            # The main thread continues dispatching Tk's animation and window events.
            try: self.update()
            except Exception: pass
        if failure: raise failure
        added=added or []
        self.rs.extend(added)
        for i,r in enumerate(self.rs,1): r.idx=i
        self.deep_done=True
        self.setstatus(f'סריקה עמוקה הושלמה — נוספו {len(added)} משאבי מדיה')

    def filter(self):
        q=self.q.get().lower();t=self.typ.get()
        def ok(r):
            if self.mode=='files' and not r.is_file:return False
            if self.mode=='images' and r.kind not in IMG:return False
            if self.mode=='media' and r.kind not in AUD:return False
            if q and q not in f'{r.kind} {r.label} {r.parent} {r.off:x} {r.size} {r.w} {r.h}'.lower():return False
            if t=='הכל':return True
            if t=='קבצי PAC':return r.is_file
            if t=='תמונות':return r.kind in IMG
            if t=='שמע':return r.kind in AUD
            return r.kind==t
        self.tree.delete(*self.tree.get_children())
        for r in self.rs:
            if ok(r):self.tree.insert('','end',iid=str(r.idx),values=(r.kind,r.label,f'0x{r.off:08X}' if r.off else '—',f'{r.size:,}' if r.size else '—',f'{r.w}×{r.h}' if r.w else '—','✓ שונה' if r.changed else ''))
    def get(self):
        s=self.tree.selection();
        if not s:return None
        return next((r for r in self.rs if r.idx==int(s[0])),None)
    def bytes(self,r):return r.data if r.data is not None else self.data[r.off:r.end]
    def select(self,e=None):
        r=self.get();self.sel=r
        if not r:return
        d=self.bytes(r);self.titlelbl.config(text=f'{r.kind}  •  0x{r.off:08X}');self.info.delete('1.0','end');self.info.insert('end',f'סוג: {r.kind}\nOffset: 0x{r.off:08X}\nגודל: {len(d):,} / {r.size:,} bytes\nמידות: {r.w}×{r.h}\nSHA-256: {hashlib.sha256(d).hexdigest()}\nמצב: {"שונה" if r.changed else "מקורי"}\n')
        if r.kind in IMG:self.showimg(r)
        elif r.kind in AUD:self.preview.config(image='',text=f'🎵\n\n{r.kind}\n\nלחץ על ▶ נגן',fg='#cbd5e1')
        elif r.is_file:
            # PAC partition: try direct image/audio preview too.
            d=self.bytes(r)
            try:
                im=Image.open(io.BytesIO(d)); self.showimg_data(d)
            except Exception:
                self.preview.config(image='',text=f'📦\n\n{r.name or r.label}\n\nזהו קובץ/מחיצה בתוך ה-PAC.\nאפשר לייצא אותו לבדיקה או לסריקה עמוקה.',fg='#cbd5e1')
        else:
            self.preview.config(image='',text='אין תצוגה')
    def showimg_data(self,d):
        im,decoder=self._display_decode_image(d,None)
        if im is None: raise ValueError(decoder)
        im=im.convert('RGBA')
        im.thumbnail((max(300,self.preview.winfo_width()-30),max(250,self.preview.winfo_height()-30)),Image.Resampling.LANCZOS)
        bg=Image.new('RGB',im.size,'#d1d5db'); bg.paste(im,mask=im.getchannel('A'))
        self.tkimg=ImageTk.PhotoImage(bg); self.preview.config(image=self.tkimg,text='')

    def showimg(self,r):
        d=self.bytes(r)
        im,decoder=self._display_decode_image(d,r)
        if im is None:
            self.preview.config(image='',text='לא ניתן להציג את התמונה\n'+decoder,fg='#fca5a5');return
        im=im.convert('RGBA')
        im.thumbnail((max(300,self.preview.winfo_width()-30),max(250,self.preview.winfo_height()-30)),Image.Resampling.LANCZOS)
        bg=Image.new('RGB',im.size,'#d1d5db');bg.paste(im,mask=im.getchannel('A'));self.tkimg=ImageTk.PhotoImage(bg);self.preview.config(image=self.tkimg,text='')
    def export(self):
        r=self.get();
        if not r:return messagebox.showwarning('ייצוא','בחר משאב')
        ext={'JPEG':'.jpg','TIFF':'.tiff'}.get(r.kind,'.'+r.kind.lower());p=filedialog.asksaveasfilename(initialfile=f'{Path(r.name).stem if r.name else r.kind}_{r.off:08X}{ext}',filetypes=[('All','*.*')]);
        if p:Path(p).write_bytes(self.bytes(r));self.setstatus('המשאב יוצא')
    def replace(self):
        r=self.get();
        if not r or not r.size:return messagebox.showwarning('החלפה','בחר קובץ/משאב עם מקום שמור')
        p=filedialog.askopenfilename(filetypes=[('כל סוגי הקבצים','*.*')]);
        if not p:return
        d=Path(p).read_bytes();self.setdata(r,d)
    def setdata(self,r,d):
        if r.is_file and r.kind=='ENTRY':
            return messagebox.showwarning('החלפה','זו רשומת PAC ללא שטח נתונים.')
        # Never put a normal PNG/BMP directly into a proprietary compressed image slot.
        # That was the main reason edited PAC files could boot as corrupt.
        old=self.data[r.off:r.end]
        if not r.is_file and old[:2]==b'BM' and len(old)>=34 and struct.unpack_from('<I',old,30)[0]==0x1003:
            return messagebox.showwarning('פורמט תמונה','המשאב הוא BMP 565-RLE. יש להשתמש ב-עורך תמונה; התוכנה תדחוס אותו חזרה לפורמט המקורי.')
        if len(d)>r.size:return messagebox.showwarning('גדול מדי',f'הקובץ החדש הוא {len(d):,} bytes, המקום הוא {r.size:,} bytes.\nערוך/דחוס אותו כדי שייכנס.')
        if not r.is_file and old[:2]==b'BM' and old[30:34]!=b'\x00\x00\x00\x00' and d[:2] not in (b'BM',):
            return messagebox.showwarning('פורמט','החלפה ישירה של משאב דחוס חסומה כדי למנוע PAC פגום.')
        r.data=d+b'\0'*(r.size-len(d));r.changed=True;self.filter();self.tree.selection_set(str(r.idx));self.select();self.setstatus('המשאב הוחלף')
    def edit(self):
        r=self.get();
        if not r:return messagebox.showwarning('עורך','בחר תמונה')
        im,decoder=self._display_decode_image(self.bytes(r),r)
        if im is None:
            return messagebox.showwarning('עורך','לא הצלחתי לפענח את התמונה לעריכה.\n\n'+decoder+'\n\nהמשאב נשאר ללא שינוי.')
        Editor(self,r,im,self.applyimg)
    def applyimg(self,im,r):
        original=self.data[r.off:r.end]
        proprietary=(not r.is_file and original[:2]==b'BM' and len(original)>=34 and struct.unpack_from('<I',original,30)[0]==0x1003)
        if proprietary:
            if not self.native.ok:
                return messagebox.showwarning('דחיסה','לא ניתן לדחוס את 565-RLE בלי ImgOptm.dll + Python 32-bit.\nהמשאב נשאר ללא שינוי כדי לא ליצור PAC פגום.\n\n'+self.native.reason)
            b=io.BytesIO(); im.convert('RGB').save(b,format='BMP')
            packed=self.native.encode(b.getvalue())
            if not packed:return messagebox.showwarning('דחיסה','ImgOptm.dll לא הצליח לדחוס את התמונה.')
            if len(packed)>r.size:return messagebox.showwarning('גדול מדי',f'הקובץ הדחוס הוא {len(packed):,} bytes, והמקום המקורי הוא {r.size:,}.\nהקטן את התמונה/איכותה.')
            r.data=packed+b'\0'*(r.size-len(packed));r.changed=True;self.filter();self.tree.selection_set(str(r.idx));self.select();self.setstatus('התמונה נדחסה חזרה ל-565-RLE');return
        fmt={'PNG':'PNG','JPEG':'JPEG','GIF':'GIF','BMP':'BMP','TIFF':'TIFF','WEBP':'WEBP'}.get(r.kind,'PNG');best=None
        if fmt=='JPEG':
            for q in range(95,4,-5):
                b=io.BytesIO();im.convert('RGB').save(b,format='JPEG',quality=q,optimize=True)
                if b.tell()<=r.size:best=b.getvalue();break
        elif fmt=='WEBP':
            for q in range(90,4,-5):
                b=io.BytesIO();im.save(b,format='WEBP',quality=q,method=6)
                if b.tell()<=r.size:best=b.getvalue();break
        else:
            b=io.BytesIO();im.convert('P',palette=Image.Palette.ADAPTIVE,colors=256).save(b,format='GIF',optimize=True) if fmt=='GIF' else im.convert('RGB' if fmt in ('BMP','JPEG') else 'RGBA').save(b,format=fmt,optimize=True);best=b.getvalue()
        if best is None:return messagebox.showwarning('לא נכנס','לא הצלחתי לדחוס את התמונה לגודל המקורי')
        self.setdata(r,best)
    # ---------- RGB565 / resource helpers ----------
    def _rgb565_image(self, raw, w, h, endian='little', swap_rb=False):
        need=w*h*2
        if w<=0 or h<=0 or len(raw)<need: return None
        pix=bytearray(w*h*3)
        j=0
        for i in range(0,need,2):
            v=int.from_bytes(raw[i:i+2],endian)
            r=((v>>11)&31)*255//31
            g=((v>>5)&63)*255//63
            b=(v&31)*255//31
            if swap_rb:r,b=b,r
            pix[j:j+3]=bytes((r,g,b)); j+=3
        return Image.frombytes('RGB',(w,h),bytes(pix))

    def decode565_dialog(self,r=None):
        if r is None:r=self.get()
        if not r or r.is_file:
            return messagebox.showwarning('RGB565','בחר משאב תמונה פנימי')
        # For proprietary compressed resources, let the user supply dimensions
        # when the resource table did not expose them.
        w,h=r.w,r.h
        if not w or not h:
            d=simpledialog.askstring('RGB565','הזן רוחב,גובה:',parent=self)
            if not d:return
            try:w,h=map(int,re.split(r'[, xX]+',d.strip()))
            except Exception:return messagebox.showerror('RGB565','לדוגמה: 240,320',parent=self)
        raw=self.bytes(r)
        # Try a set of common RGB565 RLE layouts. The first successful candidate
        # is previewed; original bytes remain untouched until explicit Replace.
        candidates=[]
        # Raw RGB565
        candidates.append(raw)
        # Simple pair-RLE: count(1) + pixel(2), count==0 as literal block marker.
        for count_first in (True,False):
            out=bytearray(); p=0
            while p+3<=len(raw) and len(out)<w*h*2:
                if count_first:
                    c=raw[p]; px=raw[p+1:p+3]; p+=3
                else:
                    px=raw[p:p+2]; c=raw[p+2]; p+=3
                if c==0 or c>255: break
                out.extend(px*c)
            if len(out)>=w*h*2:candidates.append(bytes(out))
        # 16-bit count + 16-bit pixel
        out=bytearray();p=0
        while p+4<=len(raw) and len(out)<w*h*2:
            c=int.from_bytes(raw[p:p+2],'little'); px=raw[p+2:p+4]; p+=4
            if not (1<=c<=w*h): break
            out.extend(px*c)
        if len(out)>=w*h*2:candidates.append(bytes(out))
        for raw2 in candidates:
            for endian in ('little','big'):
                im=self._rgb565_image(raw2,w,h,endian)
                if im:
                    self._show_image_window(im,f'RGB565 — {r.kind} @ 0x{r.off:08X}')
                    return
        messagebox.showinfo('RGB565','לא הצלחתי לפענח את המשאב במבני RGB565/RLE הידועים.\nהנתונים המקוריים לא שונו.\n\nאפשר עדיין לייצא את המשאב הגולמי לבדיקה.',parent=self)

    def _show_image_window(self,im,title):
        w=tk.Toplevel(self);w.title(title);w.geometry('900x700');w.configure(bg='#0b1220')
        cv=tk.Canvas(w,bg='#050a12',highlightthickness=0);cv.pack(fill='both',expand=True,padx=12,pady=12)
        def refresh(_=None):
            cv.delete('all');x=im.copy();x.thumbnail((max(100,cv.winfo_width()-30),max(100,cv.winfo_height()-30)),Image.Resampling.NEAREST)
            ph=ImageTk.PhotoImage(x);w._ph=ph;cv.create_image(cv.winfo_width()//2,cv.winfo_height()//2,image=ph)
        w.bind('<Configure>',refresh);refresh()

    # ---------- Exact NV Item 680 editor ----------
    # 4.3 deliberately does NOT rebuild or heuristically rewrite the NV file.
    # It locates the exact 680 element:
    #   A8 02 CC 00 + 51 little-endian DWORDs.
    # IMPORTANT: DWORD slot 0 is the ACTIVE-ITEM COUNT; slots 1..50 are icon codes.
    # The original firmware has 24 in slot 0 followed by 23 icon codes.
    # This distinction is essential: writing 03 as slot 0 makes the phone show 3 icons.
    MENU_NAMES = {
        0x01:'הודעות', 0x02:'אנשי קשר', 0x03:'יומן שיחות', 0x04:'גלריה',
        0x05:'מצלמה', 0x06:'הגדרות', 0x07:'קבצים', 0x08:'וידאו',
        0x09:'מוזיקה', 0x0A:'שעון מעורר', 0x0B:'רדיו', 0x0C:'רשמקול',
        0x0D:'לוח שנה', 0x0E:'מחשבון', 0x0F:'תוספות', 0x10:'מונים',
        0x11:'אינטרנט', 0x12:'Mobile Store', 0x13:'Facebook', 0x14:'Twitter',
        0x17:'פנס', 0x18:'Snake', 0x19:'English with Oxford',
        0x1A:'Ninja Up', 0x1B:'Racing Attack', 0x1C:'משחקים',
        0x1D:'Zman Hayom / אזורי', 0x1E:'Claro / אזורי', 0x1F:'Telcel',
        0x93:'זמני היום', 0x94:'זמני היום',
    }

    # The documented 225/215 2020 order, used only as a safe reference preset.
    STANDARD_225_2020 = [
        0x03,0x02,0x04,0x11,0x01,0x05,0x13,0x18,
        0x0B,0x09,0x08,0x06,0x19,0x1A,0x1B,0x0E,
        0x0A,0x1C,0x0C,0x0F,0x17,0x07,0x10,0x0D
    ]

    def _find_nv680_exact(self):
        """Find the exact Item 680 in the actual PAC NV file.
        We require the documented header A8 02 CC 00 and exactly 51 DWORDs.
        No broad 'looks like menu' heuristic is used.
        """
        candidates=[]
        for r in self.rs:
            if not r.is_file or not r.size:
                continue
            name=(r.name or '').lower()
            if 'nv' not in name:
                continue
            d=self.bytes(r)
            needle=b'\xA8\x02\xCC\x00'
            pos=0
            while True:
                q=d.find(needle,pos)
                if q<0: break
                end=q+4+0xCC
                if end<=len(d):
                    raw=d[q+4:end]
                    if len(raw)==204:
                        vals=[int.from_bytes(raw[i:i+4],'little') for i in range(0,204,4)]
                        # Slot 0 is the item count; remaining slots are byte-sized icon codes.
                        if 0 <= vals[0] <= 50 and all(0 <= x <= 0xFF for x in vals[1:]):
                            candidates.append((r,q,vals))
                pos=q+1
        if len(candidates)==1:
            return candidates[0]
        if len(candidates)>1:
            # Prefer the candidate whose first active values match the known
            # Nokia 225/215 2020 menu object family.
            fam=set(self.MENU_NAMES)
            ranked=sorted(candidates,key=lambda z:sum(x in fam for x in z[2]),reverse=True)
            if sum(x in fam for x in ranked[0][2]) >= 10:
                return ranked[0]
        return None

    def menu_editor(self):
        if not self.data:
            return messagebox.showwarning('עורך תפריט','פתח PAC קודם')

        found=self._find_nv680_exact()
        if not found:
            return messagebox.showwarning(
                'עורך תפריט',
                'לא נמצא Item 680 מדויק (A8 02 CC 00 + 204 בתים) בתוך קובץ NV של ה-PAC.'
            )

        nv,p,original_slots=found
        slot_count=50
        original_slots=list(original_slots)
        menu_count=original_slots[0]
        original_active=[x for x in original_slots[1:] if x != 0][:menu_count]

        # Palette: all codes that are already active in THIS firmware are safe.
        # Mobile Store remains visible because the user explicitly needs it.
        # Other documented 2020 objects are shown as optional, never inserted by
        # a preset automatically.
        supported=[]
        for x in original_active:
            if x not in supported:
                supported.append(x)
        for x in (0x0D,0x12,0x14,0x93,0x94):
            if x not in supported:
                supported.append(x)

        current=list(original_active)

        w=tk.Toplevel(self)
        w.title('Nokia 225 4G  •  עורך תפריט 4.17')
